
#include <stdint.h>

#include "bootloader.h"

/* START_UPDATE packet generated by Python.
   The final CRC byte is deliberately corrupted:
   Correct CRC: B0
   Corrupted CRC: B1
*/

static const uint8_t corrupted_packet[20] =
{
    0xAAU, 0x55U,
    0x01U, 0x01U,
    0x00U, 0x00U,
    0x00U, 0x08U,
    0x00U, 0x00U, 0x00U, 0x10U,
    0xF4U, 0xA7U, 0xFDU, 0x67U,
    0xEDU, 0xEDU, 0xD5U, 0xB1U
};

/* Debugger result variables */
volatile uint8_t bad_crc_state = 0xFFU;
volatile uint8_t bad_crc_test_complete = 0U;

int main(void)
{
    uint32_t i;

    /* Initialize bootloader */
    Bootloader_Init();

    /* Inject corrupted packet byte by byte */
    for (i = 0U; i < 20U; i++)
    {
        Bootloader_TestInjectByte(corrupted_packet[i]);
    }

    /* Bootloader should remain in IDLE state */
    bad_crc_state = Bootloader_GetState();

    /* Mark test complete */
    bad_crc_test_complete = 1U;

    /* Stop for debugger inspection */
    while (1)
    {
    }
}
